#!/bin/sh
# Generated by grader_matrix: same artifacts, same tools, every run.
crashcap=''
if [ ! -f ./crashcap.so ] && [ -f ./crashcap.c ] && command -v gcc >/dev/null 2>&1; then
  gcc -shared -fPIC -O1 -o ./crashcap.so ./crashcap.c -ldl >/dev/null 2>&1 || true
fi
[ -f ./crashcap.so ] && crashcap='./crashcap.so'
echo '[CPG_LABEL] benign_sh_size_24.cubin BENIGN'
echo '[CPG_LABEL] poc_sh_size_0.cubin MALICIOUS'
echo '[CPG_LABEL] ctrl_sh_size_restored_24.cubin CONTROL'
for artifact in benign_sh_size_24.cubin poc_sh_size_0.cubin ctrl_sh_size_restored_24.cubin; do
  [ -f "$artifact" ] || continue
  base=$(basename "$artifact")
  rm -f ".cc.$base"
  CRASHCAP_OUT=".cc.$base" LD_PRELOAD="$crashcap" nvdisasm "$artifact" > /dev/null 2>&1
  rc=$?
  echo "[CPG_RUN] $base::nvdisasm exit=$rc"
  if [ -f ".cc.$base" ]; then sed "s/^/[CPG_CRASH] $base /" ".cc.$base"; rm -f ".cc.$base"; fi
done
true
